@Injectable()
export class IpFilterMiddleware implements NestMiddleware {
    constructor(private readonly blacklist: BlacklistService) {}   // oddiy servis kabi inject

    use(req: Request, res: Response, next: NextFunction) {
        if (this.blacklist.isBlocked(req.ip ?? "")) {
            throw new ForbiddenException("IP manzil bloklangan")
        }
        next()
    }
}

@Injectable()
export class AuthMiddleware implements NestMiddleware {
    constructor(private readonly tokens: TokenService) {}

    async use(req: Request, res: Response, next: NextFunction) {
        const token = req.headers.authorization?.replace("Bearer ", "")
        const user = token ? await this.tokens.verify(token) : null   // asinxron ish
        if (!user) throw new UnauthorizedException("Token yaroqsiz")
        res.locals.user = user    // keyingi bosqichlar uchun
        next()
    }
}

