import { Controller, Get, Injectable, MiddlewareConsumer, Module, NestMiddleware, NestModule, Req } from "@nestjs/common"
import type { NextFunction, Request, Response } from "express"

@Injectable()
class RequestIdMiddleware implements NestMiddleware {
    private counter = 0
    use(req: Request & { id?: string }, res: Response, next: NextFunction) {
        req.id = (req.headers["x-request-id"] as string) ?? `req-${++this.counter}`
        res.setHeader("X-Request-Id", req.id)
        next()
    }
}

