type LangRequest = Request & { lang?: string }

@Injectable()
class LangMiddleware implements NestMiddleware {
    use(req: LangRequest, _res: Response, next: NextFunction) {
        // acceptsLanguages — Accept-Language dan eng mosini tanlaydi; topilmasa "uz"
        req.lang = req.acceptsLanguages("uz", "ru", "en") || "uz"
        next()
    }
}

