import { Injectable, NestMiddleware } from "@nestjs/common"
import { Test } from "@nestjs/testing"
import type { NextFunction, Request, Response } from "express"

@Injectable()
class BlacklistService {
    isBlocked(ip: string) { return ip === "10.0.0.66" }
}

@Injectable()
class IpFilterMiddleware implements NestMiddleware {
    constructor(private readonly blacklist: BlacklistService) {}
    use(req: Request, res: Response, next: NextFunction) {
        if (this.blacklist.isBlocked(req.ip ?? "")) { res.status(403).end(); return }
        next()
    }
}

async function main() {
    // BlacklistService o'rniga soxta (mock) variant beramiz
    const moduleRef = await Test.createTestingModule({
        providers: [IpFilterMiddleware, { provide: BlacklistService, useValue: { isBlocked: (ip: string) => ip === "1.1.1.1" } }],
    }).compile()
    const middleware = moduleRef.get(IpFilterMiddleware)

    for (const ip of ["1.1.1.1", "2.2.2.2"]) {
        let status = 200
        let nextCalled = false
        const res = { status(code: number) { status = code; return this }, end() {} } as unknown as Response
        middleware.use({ ip } as Request, res, () => { nextCalled = true })
        console.log(ip, "→ status:", status, "| next:", nextCalled)
    }
}
main()

