import { Controller, Injectable, MiddlewareConsumer, Module, NestMiddleware, NestModule, Post } from "@nestjs/common"
import { AsyncLocalStorage } from "node:async_hooks"
import type { NextFunction, Request, Response } from "express"

const storage = new AsyncLocalStorage<{ requestId: string }>()

@Injectable()
class ContextMiddleware implements NestMiddleware {
    private counter = 0
    use(_req: Request, _res: Response, next: NextFunction) {
        // next() ni storage.run ichida chaqiramiz: keyingi barcha bosqichlar shu kontekstda ishlaydi
        storage.run({ requestId: `r-${++this.counter}` }, () => next())
    }
}

