import { Controller, Get, MiddlewareConsumer, Module, NestModule, Query } from "@nestjs/common"

function cleanQuery(req: any, _res: any, next: () => void) {
    const cleaned: Record<string, string> = {}
    for (const [k, v] of Object.entries<string>(req.query)) {
        const t = String(v).trim()
        if (t) cleaned[k] = t
    }
    Object.defineProperty(req, "query", { value: cleaned, writable: true })
    next()
}

