import { Controller, Get, Module } from "@nestjs/common"
import type { NextFunction, Request, Response } from "express"

type Mw = (q: Request, r: Response, n: NextFunction) => void
const compose = (...mws: Mw[]): Mw => (q, r, n) => { let i = 0; const step = () => (i < mws.length ? mws[i++](q, r, step) : n()); step() }
const a: Mw = (_q, r, n) => { r.setHeader("X-A", "1"); n() }
