const CORS_ORIGINS = "CORS_ORIGINS"

@Injectable()
class OriginCheckMiddleware implements NestMiddleware {
    constructor(@Inject(CORS_ORIGINS) private readonly origins: string[]) {}
    use(req: Request, res: Response, next: NextFunction) {
        const origin = req.headers.origin
        if (origin && !this.origins.includes(origin)) { res.status(403).json({ message: `Origin ruxsat etilmagan: ${origin}` }); return }
        next()
    }
}

